import { createSlice } from "@reduxjs/toolkit";

const activate_search = {

  city_from:'',
  let_input_from:false,
  set_activate:false,
  input:'',

}


const activate_from_city = createSlice({
  name: 'to city',
  initialState: {
    value: activate_search
  },
  reducers: {
    activate_from_city_func: (state, action) => {
      state.value = action.payload;
    },



    
  }

});

export const {activate_from_city_func} = activate_from_city.actions;
export default activate_from_city.reducer;
