import React, {useState} from 'react'
import '../../CSS/Figma.css';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faLocationDot, faPhone, faAddressCard } from '@fortawesome/free-solid-svg-icons';
import Reviews from './Reviews';
import Figma_pics from './Figma_pics';
import My_skills from './My_skills';
import Main_openning from '../Redux_DIR/Redux_portfolio/Main_openning';

function Figma() {

    const [revs, setRevs] = useState(false)
    const [my_pics, setMypics] = useState(false)
    const [redux_slide, setRedux_slide] = useState(false)
    
    const start = () =>{
       setMypics(true)
    }

    const rev_comp = () =>{
        setRevs(true)
    }

    const red_slide = () =>{
        setRedux_slide(true)
    }

    const collection = {my_pics, revs, redux_slide, setRedux_slide, setMypics, setRevs}
  return (
    <div className='shoe_store'>
        <div style={{height:'100%', width:'100%'}}>
            {/* this <iframe /> showcases the rotating 3D keyboard on the opening page**/}
           {<iframe
            id="splineFrame"
            src="https://my.spline.design/untitled-pdDU2YkQAKSTv0gR0khuO2tO"
            frameborder="0"
            width="100%"
            height="99%"
            >
        </iframe>}
        </div>
        
        <div className='textx'>
            <div className='text_title'>
                Welcome To one of my Best Porfolios
            </div>

            <div className='explanation'>
                You are currently looking at the work of the greatest front end develiper in Kenya.
            </div>
                 <div className='contacts_mp' style={{ }}>
                    {/* here are all the details about me**/}
                      <div style={{display:'flex', alignItems:'center', gap:'5px', marginBottom:'10px' }}>
                         <FontAwesomeIcon style={{color:'white'}} icon={faAddressCard} />
                         <div style={{color:'white', fontSize:'12px'}}>Kevin Mukoya</div>
                     </div>
                     <div style={{display:'flex', alignItems:'center', gap:'5px', marginBottom:'10px' }}>
                         <FontAwesomeIcon style={{color:'white'}} icon={faLocationDot} />
                         <div style={{color:'white', fontSize:'12px'}}>Nairobi, Kenya</div>
                     </div>

                     <div style={{display:'flex', alignItems:'center', gap:'5px', marginBottom:'10px' }}>
                         <FontAwesomeIcon style={{color:'white'}} icon={faPhone} />
                         <div style={{color:'white', fontSize:'12px'}}>+254 726 270 922</div>
                     </div>
                 </div>

                 
            <div onClick={start} className='get_started'>
                {/* this button activates '<Figma_pics/ >' the part that shows you the building blocks of this site**/}
                SEE SITE'S BUILDING TOOLS
            </div>
            <div onClick={red_slide} className='get_started'>
                {/* this button activates '<Main_opening />' the part that showcases my skills in Redux**/}
                SEE MY OTHER DEMO
            </div>
        </div>
        

       

        <div className='bar'>
            <div onClick={rev_comp} className='sign-IN'>
                SEE REVIEWS
            </div>
        </div>

        {revs?( <div className='reviews'>
            <Reviews collection={collection} />
        </div>):('')}
        
        {my_pics?(<div className='my_work'>
            <Figma_pics collection={collection} />
        </div>):('')}

        {redux_slide?(<div className='my_work'>
            <Main_openning collection={collection} />
        </div>):('')}
        
        
        <div className='my_skills'><My_skills /></div>
       
        </div>
  )
}

export default Figma