import { createSlice } from "@reduxjs/toolkit";

const activate_search = {
  input:'',
  to:'', 
  set_activate:false, 
  set_flight_details:false, 
  city_from_iataCode:'', 
  city_to_iataCode:'',
  city_from:'', 
  city_to:'', 
  date:'',  
  let_input_to:false,
  let_input_from:false
}

const activate_search_to = {
  input:'',
  to:'', 
  set_activate:false, 
  set_flight_details:false, 
  city_from_iataCode:'', 
  city_to_iataCode:'',
  city_from:'', 
  city_to:'', 
  date:'',  
  let_input_to:false,
  let_input_from:false
}
const activate_deactivate = createSlice({
  name: 'activate_search',
  initialState: {
    value: activate_search
  },
  reducers: {
    activate: (state, action) => {
      state.value = action.payload;
    },

    activate_to: (state, action) => {
      state.value = activate_search_to;
    },

     deactivate: (state) => {
      state.value = activate_search;
    },

    
  }

});

export const { activate, deactivate, activate_to } = activate_deactivate.actions;
export default activate_deactivate.reducer;
