import React, { useEffect, useRef } from "react";
import {
  createChart,
  CandlestickSeries,
} from "lightweight-charts";

const CandleChart = () => {
  const chartContainer = useRef(null);
  const candleData = useRef([]);
  const lastPrice = useRef(100);
  const currentTime = useRef(Math.floor(Date.now() / 1000));

  useEffect(() => {
    const chart = createChart(chartContainer.current, {
      width: 800,
      height: 400,
      timeScale: {
        timeVisible: true,
        secondsVisible: true,
      },
    });

    const candleSeries = chart.addSeries(CandlestickSeries, {
      upColor: "green",
      downColor: "red",
      wickUpColor: "green",
      wickDownColor: "red",
    });

    const interval = setInterval(() => {
      currentTime.current += 1;
      const time = currentTime.current;

      // simulate ticks
      const ticks = [];
      for (let i = 0; i < 10; i++) {
        const change = (Math.random() - 0.5) * 2;
        lastPrice.current += change;
        ticks.push(Number(lastPrice.current.toFixed(2)));
      }

      const candle = {
        time,
        open: ticks[0],
        close: ticks[ticks.length - 1],
        high: Math.max(...ticks),
        low: Math.min(...ticks),
      };

      candleData.current.push(candle);
      candleSeries.update(candle);

      // 🔥 ATR STEP: RANGE OF LAST 5 CANDLES
     if (candleData.current.length >= 3) {
  const last5 = candleData.current.slice(-5);

  const ranges = last5.map(c =>
    Number((c.high - c.low).toFixed(2))
  );

  const average =
    ranges.reduce((sum, r) => sum + r, 0) / ranges.length;

  if (average < 2.3) {
    console.log(
      "Take Action"
    );
  }

  else if (average > 2.3){
    console.log('proceed')
  }
}


    }, 1000);

    return () => {
      clearInterval(interval);
      chart.remove();
    };
  }, []);

  return <div ref={chartContainer} />;
};

export default CandleChart;
