import { createSlice } from "@reduxjs/toolkit";

const userAlert = createSlice({
  name: 'alert',
  initialState: {
    value: ''
  },
  reducers: {
    alert: (state, action) => {
      state.value = action.payload;
    },

  }

});

export const { alert } = userAlert.actions;
export default userAlert.reducer;
