import { createSlice } from "@reduxjs/toolkit";

const budget_array = {price: 0,items: 0,}

const Add_purchase = createSlice({
  name: 'add_purchase',
  initialState: {
    value: budget_array
  },
  reducers: {
    buy: (state, action) => {
      state.value = action.payload;
    },

     cancel: (state) => {
      state.value = budget_array;
    },

    
  }

});

export const { buy, cancel } = Add_purchase.actions;
export default Add_purchase.reducer;
