import React, { useState } from "react";
import "./CSS.css";
import BG from "./icone.png"

const Registration = () => {

  const [errors, setErrors] = useState({});

  const [firstName, setFirstName] = useState('')
  const [secondtName, setSecondName] = useState('')
  const [phone, setPhone] = useState('')
  const [alt_phone, setAltphone] = useState('')
  const [email, setEmail] = useState('')
  const [gender, setGender] = useState('male')
  const [IYF_course, setIYF_C] = useState('')
  const [location, setLocation] = useState('')
  const [fac, setFac] = useState('none')
  const [day, setDay] = useState('')
  const [time, setTime] = useState('')
  const [accom, setAccom] = useState('no')

  const [loading, setLoading] = useState(false)
  

  const array = [
    {'day':'Monday', 'time':'morning', 'late':'evening'},
    {'day':'Tueday', 'time':'morning', 'late':'evening'},
    {'day':'Wednesday', 'time':'morning', 'late':'evening'},
    {'day':'Thursday', 'time':'morning', 'late':'evening'},
    {'day':'Friday', 'time':'morning', 'late':'evening'},
 ]

 const[days, setDays] = useState(false)

const proceed = () =>{

  if(!firstName||!secondtName||!phone||!alt_phone||!email||!gender||!IYF_course||!location||!day||!time) 
  {
    if(!firstName) alert('please add first name')
    if(!secondtName) alert('please add secondname')
    if(!phone) alert('please add first phone number')
    if(!alt_phone) alert('please add second phone number')
    if(!email) alert('please add email')
    if(!gender) alert('please add gender')
    if(!IYF_course) alert('please add your IYF course')
    if(!location) alert('please add your interested attachment location')
    if(!day) alert('please Choose an Appointment Day to our Office')

    

   
 
  }

  else{
    setLoading(true)
    submit_all()
  }
  
}

const submit_all = async () =>{

     try {
            const response = await fetch('http://advenware.atwebpages.com/backend/Upload_details.php', {
                  method: 'POST', // Change to POST
                  headers: {
                  'Content-Type': 'application/json',
                   },
                    body: JSON.stringify({
                       firstName,
                       secondtName,
                       phone,
                       alt_phone,
                       email,
                       gender,
                       IYF_course,
                       location,
                       day,
                       time,
                       accom,
                       fac
                    }),
                    });
                    const data = await response.json();
                      
                    if(data.message == 'in') setLoading(false); alert('upload done')
                       
      
                    } catch (error) {
                        console.error('Error fetching data:', error);
                        alert('error sending detail please check your connection')
                        setLoading(false)
                    }
                    finally{
                        //setLoading(false)
                    } 

}

const day_selected = ({day_coming, time}) =>{

 // alert(day_coming)
   setDay(day_coming)
   setTime(time)
   setDays(false)
}

const choose = () =>{
  setDays(true)
}

const acc_btn = () =>{
  setAccom('yes')
}

  return (
    <div className="container">
      <div className="form-section">
        <h2>Advenware Career Link for Attachment, Internship and Job Placement Application</h2>
        <p>Fill the form to register</p>

        <div className="form-grid">
          <div>
            <label>First Name</label>
            <input
              name="firstName"
             
              onChange={(e) => setFirstName(e.target.value)}
           
              placeholder="Frank"
            />
          </div>

          <div>
            <label>Last Name</label>
            <input
              name="lastName"
              
              onChange={(e) => setSecondName(e.target.value)}
             
              placeholder="Miller"
            />
          </div>

          <div>
            <label>Phone Number</label>
            <input
              name="+254712345678"
              type = 'tel'
              onChange={(e) => setPhone(e.target.value)}
    
              placeholder="+254712345678"
            />
          </div>

          <div>
            <label> Alternative Phone Number</label>
            <input
              name="+254712345678"
              type = 'tel'
              onChange={(e) => setAltphone(e.target.value)}
          
              placeholder="+254712345678"
            />
          </div>

          <div>
            <label>Email:</label>
            <input
              name="+254712345678"
              type = 'email'
              onChange={(e) => setEmail(e.target.value)}
   
              placeholder="abcd@gmail.com"
            />
          </div>

          
          <div>
            <label>Gender:</label>
            <select
               name="gender"
               onChange={(e) => setGender(e.target.value)}
             >
                 
                  <option value="male">Male</option>
                  <option value="female">Female</option>
            </select>
            {errors.city && <span className="error-text">Please select gender</span>}
          </div>

          <div>
            <label>Current Course at IYF:</label>
            <input
              name="+254712345678"
              
              onChange={(e) => setIYF_C(e.target.value)}
             
              placeholder="e.g Mind Education"
            />
          </div>

          <div>
            <label>Current Course on any institution</label>
            <input
              name="+254712345678"
              
              onChange={(e) => setFac(e.target.value)}
             
              placeholder="e.g Please mention the institution of study"
            />
          </div>

          <div>
            <label>Interested Placement Location:</label>
            <input
              name="+254712345678"
            
              onChange={(e) => setLocation(e.target.value)}
    
              placeholder="i.e Thika, Nairobi, etc"
            />
          </div>

           <div style={{display:'flex', gap:'10px', alignItems:'center'}}>
              <label>Interested in our accomodation facilities?</label>
              {accom == 'no'?(  <div>
                    <div onClick={acc_btn} className="day_btn">
                     yes
                    </div>
                 </div>):('')}
               
                  
           </div>

          <div>

            
          
          {day == ''?( <div>
          <div onClick={choose} className="day_btn">
            Choose an Appointment Day to our Office
          </div>
          </div>):(  <div>
          <div onClick={choose} className="day_btn">
           {day} {time}
          </div>
          </div>)}
    
         
          </div>

        

 </div>

          {days?(<div className="scroll_day_week">
                {array.map((data, index) => (
                 <div key={index} className="days_week">
                    <div onClick={()=>day_selected({day_coming:data.day})} className="day_of_week">{data.day}</div>
                    <div onClick={()=>day_selected({time:data.time, day_coming:data.day})} className="day_btn">{data.time}</div>
                    <div onClick={()=>day_selected({time:data.late, day_coming:data.day})} className="day_btn">{data.late}</div>
                 </div>
                ))}
          
            </div>):('')}
       
  
       {loading?( <button  className="submit-btn">Sending...</button>):( <button onClick={proceed}  className="submit-btn">Register</button>)}
       
      </div>

      <div className="image-section"><img src={BG} /></div>
    </div>
  );
};

export default Registration;