import { createSlice } from "@reduxjs/toolkit";

const activate_search = {

  city_to:'',
  let_input_to:false,
  set_activate:false,
  input:'',

}


const activate_to_city = createSlice({
  name: 'to city',
  initialState: {
    value: activate_search
  },
  reducers: {
    activate_to_city_func: (state, action) => {
      state.value = action.payload;
    },



    
  }

});

export const {activate_to_city_func} = activate_to_city.actions;
export default activate_to_city.reducer;
