import React from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';
import App from './App';
import reportWebVitals from './reportWebVitals';
import { configureStore } from "@reduxjs/toolkit";
import { Provider } from "react-redux";
import userReducer from './My_portfolio/Redux_DIR/User';
import userAlert from './My_portfolio/Redux_DIR/Alert_Redux'
import Add_Purchase from './My_portfolio/Redux_DIR/Redux_portfolio/Connecting_URL/Add_Purchase';
import Search_list from './My_portfolio/Assignment/Redux_files/Search_list';
import To_city from './My_portfolio/Assignment/Redux_files/To_city';
import From_city from './My_portfolio/Assignment/Redux_files/From_city';

const root = ReactDOM.createRoot(document.getElementById('root'));

const store = configureStore({
  reducer: {
    user: userReducer,
    alert_mess: userAlert,
    buy_shoes: Add_Purchase,
    search_list: Search_list,
    To_city,To_city,
    From_city, From_city
  }
});

root.render(
  <Provider store={store}>
    <React.StrictMode>
      <App />
    </React.StrictMode>
  </Provider>
);

reportWebVitals();
